import {makeArea,project,distance} from './engine.js';
const DB='cp-distance-v1';
async function db(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('cache');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
export async function cacheGet(key){try{const d=await db();return await new Promise((res,rej)=>{const tx=d.transaction('cache'),r=tx.objectStore('cache').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);tx.oncomplete=()=>d.close();});}catch{return null;}}
export async function cachePut(key,value){try{const d=await db();await new Promise((res,rej)=>{const tx=d.transaction('cache','readwrite');tx.objectStore('cache').put(value,key);tx.oncomplete=()=>{d.close();res();};tx.onerror=()=>rej(tx.error);});}catch{/* Private browser modes may disable storage. */}}
export async function getJSON(url,options={}){const response=await fetch(url,{...options,signal:options.signal??AbortSignal.timeout(110000)});if(!response.ok)throw new Error('HTTP '+response.status+' · '+new URL(url).hostname);return response.json();}
export function selectPark(data){const features=data.features??[],matches=features.filter(f=>{const p=f.properties??{};return Object.values(p).some(v=>typeof v==='string'&&(v==='M010'||/^central park$/i.test(v)));});const valid=(matches.length?matches:features).filter(f=>['Polygon','MultiPolygon'].includes(f.geometry?.type));if(!valid.length)throw new Error('공원 경계가 없습니다.');valid.sort((a,b)=>{const size=f=>{const ar=makeArea(f.geometry);return (ar.bounds[2]-ar.bounds[0])*(ar.bounds[3]-ar.bounds[1]);};return size(b)-size(a);});const selected=valid[0],area=makeArea(selected.geometry),w=area.bounds[2]-area.bounds[0],h=area.bounds[3]-area.bounds[1];if(w<2500||h<5000||w>6500||h>8000)throw new Error('공원 경계 크기를 확인할 수 없습니다.');return selected;}
export async function loadBoundary(){const old=await cacheGet('park');if(old)return {...old,cached:true};const url="https://data.cityofnewyork.us/resource/enfh-gkve.geojson?$where="+encodeURIComponent("gispropnum='M010'")+"&$limit=100";const data=await getJSON(url);const feature=selectPark(data);const value={feature,source:url,fetched:new Date().toISOString()};await cachePut('park',value);return value;}
export async function loadRoads(area,force=false,endpoint=0){const old=await cacheGet('osm');if(old&&!force&&Date.now()-old.fetched<7*86400000)return {...old,cached:true};const corners=[[area.bounds[0]-300,area.bounds[1]-300],[area.bounds[2]+300,area.bounds[3]+300]];const {unproject}=await import('./engine.js'),a=unproject(corners[0]),b=unproject(corners[1]);const bbox=[a[1],a[0],b[1],b[0]].join(',');const query=`[out:json][timeout:90];(way["highway"](${bbox});relation["type"="restriction"](${bbox});way["natural"="water"](${bbox}););(._;>;);out body;`;const urls=['https://overpass-api.de/api/interpreter','https://overpass.kumi.systems/api/interpreter'];try{const raw=await getJSON(urls[endpoint]??urls[0],{method:'POST',body:'data='+encodeURIComponent(query),headers:{'Content-Type':'application/x-www-form-urlencoded'}});if(raw.remark||!raw.elements?.length)throw new Error(raw.remark??'도로 데이터가 비어 있습니다.');const value={raw,source:urls[endpoint]??urls[0],fetched:Date.now(),timestamp:raw.osm3s?.timestamp_osm_base};await cachePut('osm',value);return value;}catch(error){if(old)return {...old,cached:true,outdated:true};throw error;}}
const number=v=>typeof v==='number'&&Number.isFinite(v)?v:null;
export function normalizeStations(info,status,area){const byID=new Map((status.data?.stations??[]).map(s=>[String(s.station_id),s]));return (info.data?.stations??[]).map(i=>{const s=byID.get(String(i.station_id));if(!s||!Number.isFinite(i.lon)||!Number.isFinite(i.lat))return null;const p=project([i.lon,i.lat]);if(!area.contains(p))return null;let ebikes=number(s.num_ebikes_available);if(ebikes===null&&Array.isArray(s.vehicle_types_available)){const known=s.vehicle_types_available.filter(v=>/ebike|electric/i.test(v.vehicle_type_id));if(known.length)ebikes=known.reduce((n,v)=>n+(number(v.count)??0),0);}return {id:String(i.station_id),name:i.name,p,lon:i.lon,lat:i.lat,ebikes,docks:number(s.num_docks_available),installed:s.is_installed===true||s.is_installed===1,renting:s.is_renting===true||s.is_renting===1,returning:s.is_returning===true||s.is_returning===1,timestamp:number(s.last_reported)??number(status.last_updated),battery:'unknown'};}).filter(Boolean);}
export async function loadStations(area){const index=await getJSON('https://gbfs.citibikenyc.com/gbfs/gbfs.json');const feeds=index.data?.en?.feeds??index.data?.feeds;if(!Array.isArray(feeds))throw new Error('지원되지 않는 GBFS 버전');const get=name=>{const u=feeds.find(f=>f.name===name)?.url;if(!u)throw new Error('GBFS '+name+' 없음');return getJSON(u);};const [info,status]=await Promise.all([get('station_information'),get('station_status')]);const stations=normalizeStations(info,status,area);if(!stations.length)throw new Error('대상지 정류장 상태가 없습니다.');const value={stations,version:index.version,ttl:Math.max(60,Number(status.ttl)||60),fetched:Date.now(),source_timestamp:status.last_updated};await cachePut('stations',value);return value;}
export async function hashJSON(value){const bytes=new TextEncoder().encode(JSON.stringify(value));const digest=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');}
